27	#include <sys/mman.h>  // mmap
28	#include <unistd.h>    // sysconf, sleep
29	#include <fcntl.h>     // open, close, read, access
30	#include <stdlib.h>    // getenv, arc4random_buf
31	
32	#if defined(__linux__)
33	  #include <features.h>
34	  #include <sys/prctl.h>    // THP disable, PR_SET_VMA
35	  #include <sys/sysinfo.h>  // sysinfo
36	  #if defined(__GLIBC__) && !defined(PR_SET_VMA)
37	  #include <linux/prctl.h>
38	  #endif
39	  #if defined(__GLIBC__)
40	  #include <linux/mman.h>   // linux mmap flags
41	  #else
42	  #include <sys/mman.h>
43	  #endif
44	  #if defined(__riscv) || defined(_M_RISCV)
45	    #if defined(MI_HAS_SYS_HWPROBEH)
46	      #include <sys/hwprobe.h>
47	    #elif defined(MI_HAS_ASM_HWPROBEH)
48	      #include <asm/hwprobe.h>
49	    #endif
50	  #endif
51	#elif defined(__APPLE__)
52	  #include <AvailabilityMacros.h>
53	  #include <TargetConditionals.h>
54	  #if !defined(TARGET_OS_OSX) || TARGET_OS_OSX   // see issue #879, used to be (!TARGET_IOS_IPHONE && !TARGET_IOS_SIMULATOR)
55	  #include <mach/vm_statistics.h>    // VM_MAKE_TAG, VM_FLAGS_SUPERPAGE_SIZE_2MB, etc.
56	  #endif
57	  #if !defined(MAC_OS_X_VERSION_10_7)
58	  #define MAC_OS_X_VERSION_10_7   1070
59	  #endif
60	  #include <sys/sysctl.h>
61	#elif defined(__FreeBSD__) || defined(__DragonFly__)
62	  #include <sys/param.h>
63	  #if __FreeBSD_version >= 1200000
64	  #include <sys/cpuset.h>
65	  #include <sys/domainset.h>
66	  #endif
67	  #include <sys/sysctl.h>
68	#endif
69	
70	#if (defined(__linux__) && !defined(__ANDROID__)) || defined(__FreeBSD__)
71	  #define MI_HAS_SYSCALL_H
72	  #include <sys/syscall.h>
73	#endif
74	
75	#if !defined(MADV_DONTNEED) && defined(POSIX_MADV_DONTNEED)  // QNX
76	#define MADV_DONTNEED  POSIX_MADV_DONTNEED
77	#endif
78	#if !defined(MADV_FREE) && defined(POSIX_MADV_FREE)  // QNX
79	#define MADV_FREE  POSIX_MADV_FREE
80	#endif
81	
82	#define MI_UNIX_LARGE_PAGE_SIZE (2*MI_MiB) // todo: can we query the OS for this?
83	
84	//------------------------------------------------------------------------------------
85	// Use syscalls for some primitives to allow for libraries that override open/read/close etc.
86	// and do allocation themselves; using syscalls prevents recursion when mimalloc is
87	// still initializing (issue #713)
88	// Declare inline to avoid unused function warnings.
89	//------------------------------------------------------------------------------------
90	
91	#if defined(MI_HAS_SYSCALL_H) && defined(SYS_open) && defined(SYS_close) && defined(SYS_read) && defined(SYS_access)
92	
93	static inline int mi_prim_open(const char* fpath, int open_flags) {
94	  return syscall(SYS_open,fpath,open_flags,0);
95	}
96	static inline ssize_t mi_prim_read(int fd, void* buf, size_t bufsize) {
97	  return syscall(SYS_read,fd,buf,bufsize);
98	}
99	static inline int mi_prim_close(int fd) {
100	  return syscall(SYS_close,fd);
101	}
102	static inline int mi_prim_access(const char *fpath, int mode) {
103	  return syscall(SYS_access,fpath,mode);
104	}
105	
106	#else
107	
108	static inline int mi_prim_open(const char* fpath, int open_flags) {
109	  return open(fpath,open_flags);
110	}
111	static inline ssize_t mi_prim_read(int fd, void* buf, size_t bufsize) {
112	  return read(fd,buf,bufsize);
113	}
114	static inline int mi_prim_close(int fd) {
115	  return close(fd);
116	}
117	static inline int mi_prim_access(const char *fpath, int mode) {
118	  return access(fpath,mode);
119	}
120	
121	#endif
122	
123	
124	
125	//---------------------------------------------
126	// init
127	//---------------------------------------------
128	
129	static bool unix_detect_overcommit(void) {
130	  bool os_overcommit = true;
131	  #if defined(__linux__)
132	    int fd = mi_prim_open("/proc/sys/vm/overcommit_memory", O_RDONLY);
133	    if (fd >= 0) {
134	      char buf[32];
135	      ssize_t nread = mi_prim_read(fd, &buf, sizeof(buf));
136	      mi_prim_close(fd);
137	      // <https://www.kernel.org/doc/Documentation/vm/overcommit-accounting>
138	      // 0: heuristic overcommit, 1: always overcommit, 2: never overcommit (ignore NORESERVE)
139	      if (nread >= 1) {
140	        os_overcommit = (buf[0] == '0' || buf[0] == '1');
141	      }
142	    }
143	  #elif defined(__FreeBSD__)
144	    int val = 0;
145	    size_t olen = sizeof(val);
146	    if (sysctlbyname("vm.overcommit", &val, &olen, NULL, 0) == 0) {
147	      os_overcommit = (val != 0);
148	    }
149	  #else
150	    // default: overcommit is true
151	  #endif
152	  return os_overcommit;
153	}
154	
155	static bool unix_detect_thp(void) {
156	  bool thp_enabled = false;
157	  #if defined(__linux__)
158	  int fd = mi_prim_open("/sys/kernel/mm/transparent_hugepage/enabled", O_RDONLY);
159	  if (fd >= 0) {
160	    char buf[64];
161	    ssize_t nread = mi_prim_read(fd, &buf, sizeof(buf));
162	    mi_prim_close(fd);
163	    // <https://www.kernel.org/doc/html/latest/admin-guide/mm/transhuge.html>
164	    // between brackets is the current value, for example: always [madvise] never
165	    if (nread >= 1) {
166	      if (nread > 64) { nread = 64; }
167	      thp_enabled = (_mi_strnstr(buf,nread,"[never]") == NULL);
168	    }
169	  }
170	  #endif
171	  return thp_enabled;
172	}
173	
174	// try to detect the physical memory dynamically (if possible)
175	static void unix_detect_physical_memory( size_t page_size, size_t* physical_memory_in_kib ) {
176	  #if defined(CTL_HW) && (defined(HW_PHYSMEM64) || defined(HW_MEMSIZE))  // freeBSD, macOS
177	    MI_UNUSED(page_size);
178	    int64_t physical_memory = 0;
179	    size_t length = sizeof(int64_t);
180	    #if defined(HW_PHYSMEM64)
181	    int mib[2] = { CTL_HW, HW_PHYSMEM64 };
182	    #else
183	    int mib[2] = { CTL_HW, HW_MEMSIZE };
184	    #endif
185	    const int err = sysctl(mib, 2, &physical_memory, &length, NULL, 0);
186	    if (err==0 && physical_memory > 0) {
187	      const int64_t phys_in_kib = physical_memory / MI_KiB;
188	      if (phys_in_kib > 0 && (uint64_t)phys_in_kib <= SIZE_MAX) {
189	        *physical_memory_in_kib = (size_t)phys_in_kib;
190	      }
191	    }
192	  #elif defined(__linux__)
193	    MI_UNUSED(page_size);
194	    struct sysinfo info; _mi_memzero_var(info);
195	    const int err = sysinfo(&info);
196	    if (err==0 && info.mem_unit > 0 && info.totalram <= SIZE_MAX) {
197	      if (info.mem_unit==MI_KiB) {
198	        *physical_memory_in_kib = (size_t)info.totalram;
199	      }
200	      else {
201	        size_t total = 0;
202	        if (!mi_mul_overflow((size_t)info.totalram, (size_t)info.mem_unit, &total)) {
203	          *physical_memory_in_kib = (total / MI_KiB);
204	        }
205	      }
206	    }
207	  #elif defined(_SC_PHYS_PAGES)  // do not use by default as it might cause allocation (by using `fopen` to parse /proc/meminfo) (issue #1100)
208	    const long pphys = sysconf(_SC_PHYS_PAGES);
209	    const size_t psize_in_kib = page_size / MI_KiB;
210	    if (psize_in_kib > 0 && pphys > 0 && (unsigned long)pphys <= SIZE_MAX && (size_t)pphys <= (SIZE_MAX/psize_in_kib)) {
211	      *physical_memory_in_kib = (size_t)pphys * psize_in_kib;
212	    }
213	  #endif
214	}
215	
216	// Detect the virtual address bits (currently Linux/RISC-V only)
217	static size_t unix_detect_virtual_address_bits(void) {
218	  #if defined(__riscv) || defined(_M_RISCV)
219	    #if defined(RISCV_HWPROBE_KEY_HIGHEST_VIRT_ADDRESS)
220	      struct riscv_hwprobe probe = { .key = RISCV_HWPROBE_KEY_HIGHEST_VIRT_ADDRESS, };
221	      // Prefer the GNU libc interface if available, as it can also use the VDSO
222	      #if defined(MI_HAS_SYS_HWPROBEH)
223	      if (__riscv_hwprobe(&probe, 1, 0, NULL, 0) == 0)
224	      #else
225	      if (syscall(__NR_riscv_hwprobe, &probe, 1, 0, NULL, 0) == 0)
226	      #endif
227	      {
228	        if (probe.key != -1) { // If a key is unknown to the kernel, its key field will be cleared to -1.
229	          return (MI_SIZE_BITS - mi_clz((uintptr_t)probe.value));
230	        }
231	      }
232	    #endif
233	    // Fallback to checking /proc/cpuinfo for older kernels
234	    const int fd = mi_prim_open("/proc/cpuinfo", O_RDONLY);
235	    if (fd >= 0) {
236	      char buf[2048];
237	      const ssize_t nread = mi_prim_read(fd, &buf, sizeof(buf));
238	      mi_prim_close(fd);
239	      if ((nread >= 1) && (nread <= (ssize_t)sizeof(buf))) {
240	        if (_mi_strnstr(buf, nread, "sv39")) { return 39; }
241	        else if (_mi_strnstr(buf, nread, "sv48")) { return 48; }
242	        else if (_mi_strnstr(buf, nread, "sv57")) { return 57; }
243	      }
244	    }
245	  #endif // riscv
246	  // default
247	  return MI_MAX_VABITS;
248	}
249	
250	void _mi_prim_mem_init( mi_os_mem_config_t* config )
251	{
252	  long psize = sysconf(_SC_PAGESIZE);
253	  if (psize > 0 && (unsigned long)psize < SIZE_MAX) {
254	    config->page_size = (size_t)psize;
255	    config->alloc_granularity = (size_t)psize;
256	    unix_detect_physical_memory(config->page_size, &config->physical_memory_in_kib);
257	  }
258	  config->large_page_size = MI_UNIX_LARGE_PAGE_SIZE;
259	  config->has_overcommit = unix_detect_overcommit();
260	  config->has_partial_free = true;    // mmap can free in parts
261	  config->has_virtual_reserve = true; // todo: check if this true for NetBSD?  (for anonymous mmap with PROT_NONE)
262	  config->has_transparent_huge_pages = unix_detect_thp();
263	  config->virtual_address_bits = unix_detect_virtual_address_bits();
264	
265	  // disable transparent huge pages for this process?
266	  #if (defined(__linux__) || defined(__ANDROID__)) && defined(PR_GET_THP_DISABLE)
267	  if (!mi_option_is_enabled(mi_option_allow_thp)) // disable THP if requested through an option
268	  {
269	    config->has_transparent_huge_pages = false;
270	    if (prctl(PR_GET_THP_DISABLE, 0, 0, 0, 0) == 0) {   // -1 on error, 1 if already disabled
271	      // Most likely since distros often come with always/madvise settings.
272	      // Disabling only for mimalloc process rather than touching system wide settings
273	      (void)prctl(PR_SET_THP_DISABLE, 1, 0, 0, 0);
274	    }
275	  }
276	  #endif
277	}
