294	
295	// return errno on failure
296	static int unix_madvise(void* addr, size_t size, int advice) {
297	  #if defined(__sun) || defined(_AIX)
298	  const int res = madvise((caddr_t)addr, size, advice);  // Solaris needs cast (issue #520)
299	  return (res==0 ? 0 : errno);
300	  #elif defined(__QNX__)
301	  return posix_madvise(addr, size, advice);              // posix returns errno
302	  #else
303	  const int res = madvise(addr, size, advice);           // linux returns -1 on failure and sets errno
304	  return (res==0 ? 0 : errno);
305	  #endif
306	}
307	
308	static void* unix_mmap_prim(void* addr, size_t size, int protect_flags, int flags, int fd) {
309	  void* p = mmap(addr, size, protect_flags, flags, fd, 0 /* offset */);
310	  #if defined(__linux__) && defined(PR_SET_VMA)
311	  if (p!=MAP_FAILED && p!=NULL) {
312	    prctl(PR_SET_VMA, PR_SET_VMA_ANON_NAME, p, size, "mimalloc");
313	  }
314	  #endif
315	  return p;
316	}
317	
318	static void* unix_mmap_prim_aligned(void* addr, size_t size, size_t try_alignment, int protect_flags, int flags, int fd) {
319	  MI_UNUSED(try_alignment);
320	  void* p = NULL;
321	  #if defined(MAP_ALIGNED)  // BSD
322	  if (addr == NULL && try_alignment > 1 && (try_alignment % _mi_os_page_size()) == 0) {
323	    size_t n = 0;
324	    mi_bsr(try_alignment, &n);
325	    if (((size_t)1 << n) == try_alignment && n >= 12 && n <= 30) {  // alignment is a power of 2 and 4096 <= alignment <= 1GiB
326	      p = unix_mmap_prim(addr, size, protect_flags, flags | MAP_ALIGNED(n), fd);
327	      if (p==MAP_FAILED || !_mi_is_aligned(p,try_alignment)) {
328	        int err = errno;
329	        _mi_trace_message("unable to directly request aligned OS memory (error: %d (0x%x), size: 0x%zx bytes, alignment: 0x%zx, hint address: %p)\n", err, err, size, try_alignment, addr);
330	      }
331	      if (p!=MAP_FAILED) return p;
332	      // fall back to regular mmap
333	    }
334	  }
335	  #elif defined(MAP_ALIGN)  // Solaris
336	  if (addr == NULL && try_alignment > 1 && (try_alignment % _mi_os_page_size()) == 0) {
337	    p = unix_mmap_prim((void*)try_alignment, size, protect_flags, flags | MAP_ALIGN, fd);  // addr parameter is the required alignment
338	    if (p!=MAP_FAILED) return p;
339	    // fall back to regular mmap
340	  }
341	  #endif
342	  #if (MI_INTPTR_SIZE >= 8) && !defined(MAP_ALIGNED)
343	  // on 64-bit systems, use the virtual address area after 2TiB for 4MiB aligned allocations
344	  if (addr == NULL) {
345	    void* hint = _mi_os_get_aligned_hint(try_alignment, size);
346	    if (hint != NULL) {
347	      p = unix_mmap_prim(hint, size, protect_flags, flags, fd);
348	      if (p==MAP_FAILED || !_mi_is_aligned(p,try_alignment)) {
349	        #if MI_TRACK_ENABLED  // asan sometimes does not instrument errno correctly?
350	        int err = 0;
351	        #else
352	        int err = errno;
353	        #endif
354	        _mi_trace_message("unable to directly request hinted aligned OS memory (error: %d (0x%x), size: 0x%zx bytes, alignment: 0x%zx, hint address: %p)\n", err, err, size, try_alignment, hint);
355	      }
356	      if (p!=MAP_FAILED) return p;
357	      // fall back to regular mmap
358	    }
359	  }
360	  #endif
361	  // regular mmap
362	  p = unix_mmap_prim(addr, size, protect_flags, flags, fd);
363	  if (p!=MAP_FAILED) return p;
364	  // failed to allocate
365	  return NULL;
366	}
367	
368	static int unix_mmap_fd(void) {
369	  #if defined(VM_MAKE_TAG)
370	  // macOS: tracking anonymous page with a specific ID. (All up to 98 are taken officially but LLVM sanitizers had taken 99)
371	  int os_tag = (int)mi_option_get(mi_option_os_tag);
372	  if (os_tag < 100 || os_tag > 255) { os_tag = 254; }
373	  return VM_MAKE_TAG(os_tag);
374	  #else
375	  return -1;
376	  #endif
377	}
378	
379	#if defined(MAP_ALIGNED_SUPER) || defined(MAP_HUGETLB) || defined(MAP_HUGE_1GB) || defined(MAP_HUGE_2MB) || defined(VM_FLAGS_SUPERPAGE_SIZE_2MB)
380	#define MI_OS_HAS_HUGE_PAGES  1
381	#endif
382	
383	static void* unix_mmap(void* addr, size_t size, size_t try_alignment, int protect_flags, bool large_only, bool allow_large, bool* is_large) {
384	  #if !defined(MAP_ANONYMOUS)
385	  #define MAP_ANONYMOUS  MAP_ANON
386	  #endif
387	  #if !defined(MAP_NORESERVE)
388	  #define MAP_NORESERVE  0
389	  #endif
390	  void* p = NULL;
391	  const int fd = unix_mmap_fd();
392	  int flags = MAP_PRIVATE | MAP_ANONYMOUS;
393	  if (_mi_os_has_overcommit()) {
394	    flags |= MAP_NORESERVE;
395	  }
396	  #if defined(PROT_MAX)
397	  protect_flags |= PROT_MAX(PROT_READ | PROT_WRITE); // BSD
398	  #endif
399	  // huge page allocation
400	  #if MI_OS_HAS_HUGE_PAGES
401	  if (allow_large && (large_only || (_mi_os_canuse_large_page(size, try_alignment) && mi_option_is_enabled(mi_option_allow_large_os_pages)))) {
402	    static _Atomic(size_t) large_page_try_ok; // = 0;
403	    size_t try_ok = mi_atomic_load_acquire(&large_page_try_ok);
404	    if (!large_only && try_ok > 0) {
405	      // If the OS is not configured for large OS pages, or the user does not have
406	      // enough permission, the `mmap` will always fail (but it might also fail for other reasons).
407	      // Therefore, once a large page allocation failed, we don't try again for `large_page_try_ok` times
408	      // to avoid too many failing calls to mmap.
409	      mi_atomic_cas_strong_acq_rel(&large_page_try_ok, &try_ok, try_ok - 1);
410	    }
411	    else {
412	      int lflags = flags & ~MAP_NORESERVE;  // using NORESERVE on huge pages seems to fail on Linux
413	      int lfd = fd;
414	      #ifdef MAP_ALIGNED_SUPER
415	      lflags |= MAP_ALIGNED_SUPER;
416	      #endif
417	      #ifdef MAP_HUGETLB
418	      lflags |= MAP_HUGETLB;
419	      #endif
420	      #ifdef MAP_HUGE_1GB
421	      static _Atomic(size_t) mi_huge_1gib_pages_unavailable;
422	      if (large_only && (size % MI_GiB) == 0 && (mi_atomic_load_relaxed(&mi_huge_1gib_pages_unavailable)==0)) {
423	        lflags |= MAP_HUGE_1GB;
424	      }
425	      else
426	      #endif
427	      {
428	        #ifdef MAP_HUGE_2MB
429	        lflags |= MAP_HUGE_2MB;
430	        #endif
431	      }
432	      #ifdef VM_FLAGS_SUPERPAGE_SIZE_2MB
433	      lfd |= VM_FLAGS_SUPERPAGE_SIZE_2MB;
434	      #endif
435	      if (large_only || lflags != flags) {
436	        // try large OS page allocation
437	        *is_large = true;
438	        p = unix_mmap_prim_aligned(addr, size, try_alignment, protect_flags, lflags, lfd);
439	        #ifdef MAP_HUGE_1GB
440	        if (p == NULL && (lflags & MAP_HUGE_1GB) == MAP_HUGE_1GB) {
441	          mi_atomic_store_relaxed(&mi_huge_1gib_pages_unavailable,1); // don't try huge 1GiB pages again
442	          if (large_only) {
443	            _mi_warning_message("unable to allocate huge (1GiB) page, trying large (2MiB) pages instead (errno: %i)\n", errno);
444	          }
445	          lflags = ((lflags & ~MAP_HUGE_1GB) | MAP_HUGE_2MB);
446	          p = unix_mmap_prim_aligned(addr, size, try_alignment, protect_flags, lflags, lfd);
447	        }
448	        #endif
449	        if (large_only) return p;
450	        if (p == NULL) {
451	          mi_atomic_store_release(&large_page_try_ok, (size_t)8);  // on error, don't try again for the next N allocations
452	        }
453	      }
454	    }
455	  } // huge pages
456	  #else
457	  MI_UNUSED(large_only);
458	  #endif
459	  // regular allocation
460	  if (p == NULL) {
461	    *is_large = false;
462	    p = unix_mmap_prim_aligned(addr, size, try_alignment, protect_flags, flags, fd);
463	    #if !defined(MI_NO_THP)
464	    if (p != NULL && allow_large && mi_option_is_enabled(mi_option_allow_thp) && _mi_os_canuse_large_page(size, try_alignment)) {
465	      #if defined(MADV_HUGEPAGE)
466	      // Many Linux systems don't allow MAP_HUGETLB but they support instead
467	      // transparent huge pages (THP). Generally, it is not required to call `madvise` with MADV_HUGE
468	      // though since properly aligned allocations will already use large pages if available
469	      // in that case -- in particular for our large regions (in `memory.c`).
470	      // However, some systems only allow THP if called with explicit `madvise`, so
471	      // when large OS pages are enabled for mimalloc, we call `madvise` anyways.
472	      if (unix_madvise(p, size, MADV_HUGEPAGE) == 0) {
473	        // *is_large = true; // possibly
474	      };
475	      #elif defined(__sun)
476	      struct memcntl_mha cmd = {0};
477	      cmd.mha_pagesize = _mi_os_large_page_size();
478	      cmd.mha_cmd = MHA_MAPSIZE_VA;
479	      if (memcntl((caddr_t)p, size, MC_HAT_ADVISE, (caddr_t)&cmd, 0, 0) == 0) {
480	        // *is_large = true; // possibly
481	      }
482	      #endif
483	    }
484	    #endif
485	  }
486	  return p;
487	}
488	
489	// Note: the `try_alignment` is just a hint and the returned pointer is not guaranteed to be aligned.
490	int _mi_prim_alloc(void* hint_addr, size_t size, size_t try_alignment, bool commit, bool allow_large, bool* is_large, bool* is_zero, void** addr) {
491	  mi_assert_internal(size > 0 && (size % _mi_os_page_size()) == 0);
492	  mi_assert_internal(commit || !allow_large);
493	  mi_assert_internal(try_alignment > 0);
494	  *is_zero = true;
495	  int protect_flags = (commit ? (PROT_WRITE | PROT_READ) : PROT_NONE);
496	  *addr = unix_mmap(hint_addr, size, try_alignment, protect_flags, false, allow_large, is_large);
497	  return (*addr != NULL ? 0 : errno);
498	}
