505	static void unix_mprotect_hint(int err) {
506	  #if defined(__linux__) && (MI_SECURE>=5 || MI_GUARDED) // guard page around every mimalloc page
507	  if (err == ENOMEM) {
508	    _mi_warning_message("The next warning may be caused by a low memory map limit.\n"
509	                        "  On Linux this is controlled by the vm.max_map_count -- maybe increase it?\n"
510	                        "  For example: sudo sysctl -w vm.max_map_count=262144\n");
511	  }
512	  #else
513	  MI_UNUSED(err);
514	  #endif
515	}
