520	
521	int _mi_prim_commit(void* start, size_t size, bool* is_zero) {
522	  // commit: ensure we can access the area
523	  // note: we may think that *is_zero can be true since the memory
524	  // was either from mmap PROT_NONE, or from decommit MADV_DONTNEED, but
525	  // we sometimes call commit on a range with still partially committed
526	  // memory and `mprotect` does not zero the range.
527	  *is_zero = false;
528	  int err = mprotect(start, size, (PROT_READ | PROT_WRITE));
529	  if (err != 0) {
530	    err = errno;
531	    unix_mprotect_hint(err);
532	  }
533	  return err;
534	}
535	
536	int _mi_prim_reuse(void* start, size_t size) {
537	  MI_UNUSED(start); MI_UNUSED(size);
538	  #if defined(__APPLE__) && defined(MADV_FREE_REUSE)
539	  return unix_madvise(start, size, MADV_FREE_REUSE);
540	  #endif
541	  return 0;
542	}
543	
544	int _mi_prim_decommit(void* start, size_t size, bool* needs_recommit) {
545	  int err = 0;
546	  #if 1
547	    #if defined(__APPLE__) && defined(MADV_FREE_REUSABLE)
548	      // decommit on macOS: use MADV_FREE_REUSABLE as it does immediate rss accounting (issue #1097)
549	      err = unix_madvise(start, size, MADV_FREE_REUSABLE);
550	      if (err) { err = unix_madvise(start, size, MADV_DONTNEED); }
551	    #else
552	      // decommit: use MADV_DONTNEED as it decreases rss immediately (unlike MADV_FREE)
553	      err = unix_madvise(start, size, MADV_DONTNEED);
554	    #endif
555	    #if !MI_DEBUG && MI_SECURE<=2
556	      *needs_recommit = false;
557	    #else
558	      *needs_recommit = true;
559	      mprotect(start, size, PROT_NONE);
560	    #endif
561	  #else
562	    // decommit: use mmap with MAP_FIXED and PROT_NONE to discard the existing memory (and reduce rss)
563	    *needs_recommit = true;
564	    const int fd = unix_mmap_fd();
565	    void* p = mmap(start, size, PROT_NONE, (MAP_FIXED | MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE), fd, 0);
566	    if (p != start) { err = errno; }
567	  #endif
568	  return err;
569	}
570	
571	int _mi_prim_reset(void* start, size_t size) {
572	  int err = 0;
573	
574	  // on macOS can use MADV_FREE_REUSABLE (but we disable this for now as it seems slower)
575	  #if 0 && defined(__APPLE__) && defined(MADV_FREE_REUSABLE)
576	  err = unix_madvise(start, size, MADV_FREE_REUSABLE);
577	  if (err==0) return 0;
578	  // fall through
579	  #endif
580	
581	  #if defined(MADV_FREE)
582	  // Otherwise, we try to use `MADV_FREE` as that is the fastest. A drawback though is that it
583	  // will not reduce the `rss` stats in tools like `top` even though the memory is available
584	  // to other processes. With the default `MIMALLOC_PURGE_DECOMMITS=1` we ensure that by
585	  // default `MADV_DONTNEED` is used though.
586	  static _Atomic(size_t) advice = MI_ATOMIC_VAR_INIT(MADV_FREE);
587	  int oadvice = (int)mi_atomic_load_relaxed(&advice);
588	  while ((err = unix_madvise(start, size, oadvice)) != 0 && err == EAGAIN) { /* try again */ };
589	  if (err == EINVAL && oadvice == MADV_FREE) {
590	    // if MADV_FREE is not supported, fall back to MADV_DONTNEED from now on
591	    mi_atomic_store_release(&advice, (size_t)MADV_DONTNEED);
592	    err = unix_madvise(start, size, MADV_DONTNEED);
593	  }
594	  #else
595	  err = unix_madvise(start, size, MADV_DONTNEED);
596	  #endif
597	  return err;
598	}
599	
600	int _mi_prim_protect(void* start, size_t size, bool protect) {
601	  int err = mprotect(start, size, protect ? PROT_NONE : (PROT_READ | PROT_WRITE));
602	  if (err != 0) { err = errno; }
603	  unix_mprotect_hint(err);
604	  return err;
605	}
