742	#include <time.h>
743	
744	// low resolution timer
745	static mi_msecs_t mi_prim_clock_now_lowres(void) {
746	  const int64_t ticks = (int64_t)clock();
747	  #if !defined(CLOCKS_PER_SEC)
748	    return ticks;
749	  #else
750	    if (CLOCKS_PER_SEC <= 0 || CLOCKS_PER_SEC == 1000) {
751	      return ticks;
752	    }
753	    else if (CLOCKS_PER_SEC > 0 && CLOCKS_PER_SEC < 1000) {
754	      return ticks * (1000 / (mi_msecs_t)CLOCKS_PER_SEC);
755	    }
756	    else {
757	      return ticks / ((mi_msecs_t)CLOCKS_PER_SEC / 1000);
758	    }
759	  #endif
760	}
761	
762	mi_msecs_t _mi_prim_clock_now(void) {
763	  #if defined(CLOCK_REALTIME) || defined(CLOCK_MONOTONIC)
764	    #ifdef CLOCK_MONOTONIC
765	    const clockid_t clockid = CLOCK_MONOTONIC;
766	    #else
767	    const clockid_t clockid = CLOCK_REALTIME;
768	    #endif
769	    struct timespec t;
770	    if (clock_gettime(clockid,&t) == 0) {
771	      return ((mi_msecs_t)t.tv_sec * 1000) + ((mi_msecs_t)t.tv_nsec / 1000000L);
772	    }
773	  #endif
774	  return mi_prim_clock_now_lowres();
775	}
