963	  #if defined(MI_HAS_SYSCALL_H) && defined(SYS_getrandom)
964	    #ifndef GRND_NONBLOCK
965	    #define GRND_NONBLOCK (1)
966	    #endif
967	    static _Atomic(uintptr_t) no_getrandom; // = 0
968	    if (mi_atomic_load_acquire(&no_getrandom)==0) {
969	      ssize_t ret = syscall(SYS_getrandom, buf, buf_len, GRND_NONBLOCK);
970	      if (ret >= 0) return (buf_len == (size_t)ret);
971	      if (errno != ENOSYS) return false;
972	      mi_atomic_store_release(&no_getrandom, (uintptr_t)1); // don't call again, and fall back to /dev/urandom
973	    }
974	  #endif
