980	  if (fd < 0) return false;
981	  size_t count = 0;
982	  while(count < buf_len) {
983	    ssize_t ret = mi_prim_read(fd, (char*)buf + count, buf_len - count);
984	    if (ret==0) {
985	      break;
986	    }
987	    else if (ret<0) {
988	      if (errno!=EAGAIN && errno!=EINTR) break;
989	    }
990	    else {
991	      count += ret;
992	    }
993	  }
994	  mi_prim_close(fd);
995	  return (count==buf_len);
996	}
