129	  // Set "Lock pages in memory" permission in the group policy editor
130	  // <https://devblogs.microsoft.com/oldnewthing/20110128-00/?p=11643>
131	  unsigned long err = 0;
132	  HANDLE token = NULL;
133	  BOOL ok = OpenProcessToken(GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &token);
134	  err = GetLastError();
135	  if (ok) {
136	    TOKEN_PRIVILEGES tp;
137	    ok = LookupPrivilegeValue(NULL, TEXT("SeLockMemoryPrivilege"), &tp.Privileges[0].Luid);
138	    err = GetLastError();
139	    if (ok) {
140	      tp.PrivilegeCount = 1;
141	      tp.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;
142	      ok = AdjustTokenPrivileges(token, FALSE, &tp, 0, (PTOKEN_PRIVILEGES)NULL, 0);
143	      err = GetLastError();
144	      if (ok) {
