254	int _mi_prim_free(void* addr, size_t size ) {
255	  MI_UNUSED(size);
256	  DWORD errcode = 0;
257	  bool err = (VirtualFree(addr, 0, MEM_RELEASE) == 0);
258	  if (err) { errcode = GetLastError(); }
259	  if (errcode == ERROR_INVALID_ADDRESS) {
260	    // In mi_os_mem_alloc_aligned the fallback path may have returned a pointer inside
261	    // the memory region returned by VirtualAlloc; in that case we need to free using
262	    // the start of the region.
263	    MEMORY_BASIC_INFORMATION info; _mi_memzero_var(info);
264	    err = (VirtualQuery(addr, &info, sizeof(info)) == 0);
265	    if (err) { errcode = GetLastError(); }
266	    if (!err && info.AllocationBase < addr && ((uint8_t*)addr - (uint8_t*)info.AllocationBase) < (ptrdiff_t)(4*MI_MiB)) {
267	      errcode = 0;
268	      err = (VirtualFree(info.AllocationBase, 0, MEM_RELEASE) == 0);
269	      if (err) { errcode = GetLastError(); }
270	    }
271	  }
272	  return (int)errcode;
273	}
