280	static void* win_virtual_alloc_prim_once(void* addr, size_t size, size_t try_alignment, DWORD flags) {
281	  #if (MI_INTPTR_SIZE >= 8)
282	  // on 64-bit systems, try to use the virtual address area after 2TiB for 4MiB aligned allocations
283	  if (addr == NULL) {
284	    void* hint = _mi_os_get_aligned_hint(try_alignment,size);
285	    if (hint != NULL) {
286	      void* p = VirtualAlloc(hint, size, flags, PAGE_READWRITE);
287	      if (p != NULL) return p;
288	      _mi_verbose_message("warning: unable to allocate hinted aligned OS memory (%zu bytes, error code: 0x%x, address: %p, alignment: %zu, flags: 0x%x)\n", size, GetLastError(), hint, try_alignment, flags);
289	      // fall through on error
290	    }
291	  }
292	  #endif
293	  // on modern Windows try use VirtualAlloc2 for aligned allocation
294	  if (addr == NULL && try_alignment > win_allocation_granularity && (try_alignment % _mi_os_page_size()) == 0 && pVirtualAlloc2 != NULL) {
295	    MI_MEM_ADDRESS_REQUIREMENTS reqs = { 0, 0, 0 };
296	    reqs.Alignment = try_alignment;
297	    MI_MEM_EXTENDED_PARAMETER param = { {0, 0}, {0} };
298	    param.Type.Type = MiMemExtendedParameterAddressRequirements;
299	    param.Arg.Pointer = &reqs;
300	    void* p = (*pVirtualAlloc2)(GetCurrentProcess(), addr, size, flags, PAGE_READWRITE, &param, 1);
301	    if (p != NULL) return p;
302	    _mi_warning_message("unable to allocate aligned OS memory (0x%zx bytes, error code: 0x%x, address: %p, alignment: 0x%zx, flags: 0x%x)\n", size, GetLastError(), addr, try_alignment, flags);
303	    // fall through on error
304	  }
305	  // last resort
306	  return VirtualAlloc(addr, size, flags, PAGE_READWRITE);
