311	    case ERROR_COMMITMENT_MINIMUM:
312	    case ERROR_COMMITMENT_LIMIT:
313	    case ERROR_PAGEFILE_QUOTA:
314	    case ERROR_NOT_ENOUGH_MEMORY:
315	      return true;
