321	static void* win_virtual_alloc_prim(void* addr, size_t size, size_t try_alignment, DWORD flags) {
322	  long max_retry_msecs = mi_option_get_clamp(mi_option_retry_on_oom, 0, 2000);  // at most 2 seconds
323	  if (max_retry_msecs == 1) { max_retry_msecs = 100; }  // if one sets the option to "true"
324	  for (long tries = 1; tries <= 10; tries++) {          // try at most 10 times (=2200ms)
325	    void* p = win_virtual_alloc_prim_once(addr, size, try_alignment, flags);
326	    if (p != NULL) {
327	      // success, return the address
328	      return p;
329	    }
330	    else if (max_retry_msecs > 0 && (try_alignment <= 8*MI_MiB) &&
331	              (flags&MEM_COMMIT) != 0 && (flags&MEM_LARGE_PAGES) == 0 &&
332	              win_is_out_of_memory_error(GetLastError())) {
333	      // if committing regular memory and being out-of-memory,
334	      // keep trying for a bit in case memory frees up after all. See issue #894
335	      _mi_warning_message("out-of-memory on OS allocation, try again... (attempt %lu, 0x%zx bytes, error code: 0x%x, address: %p, alignment: 0x%zx, flags: 0x%x)\n", tries, size, GetLastError(), addr, try_alignment, flags);
336	      long sleep_msecs = tries*40;  // increasing waits
337	      if (sleep_msecs > max_retry_msecs) { sleep_msecs = max_retry_msecs; }
338	      max_retry_msecs -= sleep_msecs;
339	      Sleep(sleep_msecs);
340	    }
341	    else {
342	      // otherwise return with an error
343	      break;
344	    }
345	  }
346	  return NULL;
347	}
