349	static void* win_virtual_alloc(void* addr, size_t size, size_t try_alignment, DWORD flags, bool large_only, bool allow_large, bool* is_large) {
350	  mi_assert_internal(!(large_only && !allow_large));
351	  static _Atomic(size_t) large_page_try_ok; // = 0;
352	  void* p = NULL;
353	  // Try to allocate large OS pages (2MiB) if allowed or required.
354	  if ((large_only || (_mi_os_canuse_large_page(size, try_alignment) && mi_option_is_enabled(mi_option_allow_large_os_pages)))
355	      && allow_large && (flags&MEM_COMMIT)!=0 && (flags&MEM_RESERVE)!=0)
356	  {
357	    size_t try_ok = mi_atomic_load_acquire(&large_page_try_ok);
358	    if (!large_only && try_ok > 0) {
359	      // if a large page allocation fails, it seems the calls to VirtualAlloc get very expensive.
360	      // therefore, once a large page allocation failed, we don't try again for `large_page_try_ok` times.
361	      mi_atomic_cas_strong_acq_rel(&large_page_try_ok, &try_ok, try_ok - 1);
362	    }
363	    else {
364	      // large OS pages must always reserve and commit.
365	      *is_large = true;
366	      p = win_virtual_alloc_prim(addr, size, try_alignment, flags | MEM_LARGE_PAGES);
367	      if (large_only) return p;
368	      // fall back to non-large page allocation on error (`p == NULL`).
369	      if (p == NULL) {
370	        mi_atomic_store_release(&large_page_try_ok,10UL);  // on error, don't try again for the next N allocations
371	      }
372	    }
373	  }
374	  // Fall back to regular page allocation
375	  if (p == NULL) {
376	    *is_large = ((flags&MEM_LARGE_PAGES) != 0);
377	    p = win_virtual_alloc_prim(addr, size, try_alignment, flags);
378	  }
379	  //if (p == NULL) { _mi_warning_message("unable to allocate OS memory (%zu bytes, error code: 0x%x, address: %p, alignment: %zu, flags: 0x%x, large only: %d, allow large: %d)\n", size, GetLastError(), addr, try_alignment, flags, large_only, allow_large); }
380	  return p;
381	}
382	
383	int _mi_prim_alloc(void* hint_addr, size_t size, size_t try_alignment, bool commit, bool allow_large, bool* is_large, bool* is_zero, void** addr) {
384	  mi_assert_internal(size > 0 && (size % _mi_os_page_size()) == 0);
385	  mi_assert_internal(commit || !allow_large);
386	  mi_assert_internal(try_alignment > 0);
387	  *is_zero = true;
388	  int flags = MEM_RESERVE;
389	  if (commit) { flags |= MEM_COMMIT; }
390	  *addr = win_virtual_alloc(hint_addr, size, try_alignment, flags, false, allow_large, is_large);
391	  return (*addr != NULL ? 0 : (int)GetLastError());
392	}
