402	int _mi_prim_commit(void* addr, size_t size, bool* is_zero) {
403	  *is_zero = false;
404	  /*
405	  // zero'ing only happens on an initial commit... but checking upfront seems expensive..
406	  _MEMORY_BASIC_INFORMATION meminfo; _mi_memzero_var(meminfo);
407	  if (VirtualQuery(addr, &meminfo, size) > 0) {
408	    if ((meminfo.State & MEM_COMMIT) == 0) {
409	      *is_zero = true;
410	    }
411	  }
412	  */
413	  // commit
414	  void* p = VirtualAlloc(addr, size, MEM_COMMIT, PAGE_READWRITE);
415	  if (p == NULL) return (int)GetLastError();
416	  return 0;
417	}
418	
419	int _mi_prim_decommit(void* addr, size_t size, bool* needs_recommit) {
420	  BOOL ok = VirtualFree(addr, size, MEM_DECOMMIT);
421	  *needs_recommit = true;  // for safety, assume always decommitted even in the case of an error.
422	  return (ok ? 0 : (int)GetLastError());
423	}
424	
425	int _mi_prim_reset(void* addr, size_t size) {
426	  void* p = VirtualAlloc(addr, size, MEM_RESET, PAGE_READWRITE);
427	  mi_assert_internal(p == addr);
428	  #if 0
429	  if (p != NULL) {
430	    VirtualUnlock(addr,size); // VirtualUnlock after MEM_RESET removes the memory directly from the working set
431	  }
432	  #endif
433	  return (p != NULL ? 0 : (int)GetLastError());
434	}
