441	int _mi_prim_protect(void* addr, size_t size, bool protect) {
442	  DWORD oldprotect = 0;
443	  BOOL ok = VirtualProtect(addr, size, protect ? PAGE_NOACCESS : PAGE_READWRITE, &oldprotect);
444	  return (ok ? 0 : (int)GetLastError());
445	}
