448	//---------------------------------------------
449	// Huge page allocation
450	//---------------------------------------------
451	
452	static void* _mi_prim_alloc_huge_os_pagesx(void* hint_addr, size_t size, int numa_node)
453	{
454	  const DWORD flags = MEM_LARGE_PAGES | MEM_COMMIT | MEM_RESERVE;
455	
456	  win_enable_large_os_pages(NULL);
457	
458	  MI_MEM_EXTENDED_PARAMETER params[3] = { {{0,0},{0}},{{0,0},{0}},{{0,0},{0}} };
459	  // on modern Windows try use NtAllocateVirtualMemoryEx for 1GiB huge pages
460	  static _Atomic(size_t) mi_huge_pages_available = MI_ATOMIC_VAR_INIT(1);
461	  if (pNtAllocateVirtualMemoryEx != NULL && mi_atomic_load_acquire(&mi_huge_pages_available) != 0) {
462	    params[0].Type.Type = MiMemExtendedParameterAttributeFlags;
463	    params[0].Arg.ULong64 = MI_MEM_EXTENDED_PARAMETER_NONPAGED_HUGE;
464	    ULONG param_count = 1;
465	    if (numa_node >= 0) {
466	      param_count++;
467	      params[1].Type.Type = MiMemExtendedParameterNumaNode;
468	      params[1].Arg.ULong = (unsigned)numa_node;
469	    }
470	    SIZE_T psize = size;
471	    void* base = hint_addr;
472	    LONG err = (*pNtAllocateVirtualMemoryEx)(GetCurrentProcess(), &base, &psize, flags, PAGE_READWRITE, params, param_count);
473	    if (err == 0 && base != NULL) {
474	      return base;
475	    }
476	    else {
477	      // fall back to regular large pages
478	      mi_atomic_store_release(&mi_huge_pages_available,0); // don't try further huge pages
479	      _mi_warning_message("unable to allocate using huge (1GiB) pages, trying large (2MiB) pages instead (status 0x%lx)\n", err);
480	    }
481	  }
482	  // on modern Windows try use VirtualAlloc2 for numa aware large OS page allocation
483	  if (pVirtualAlloc2 != NULL && numa_node >= 0) {
484	    params[0].Type.Type = MiMemExtendedParameterNumaNode;
485	    params[0].Arg.ULong = (unsigned)numa_node;
486	    return (*pVirtualAlloc2)(GetCurrentProcess(), hint_addr, size, flags, PAGE_READWRITE, params, 1);
487	  }
488	
489	  // otherwise use regular virtual alloc on older windows
490	  return VirtualAlloc(hint_addr, size, flags, PAGE_READWRITE);
491	}
492	
493	int _mi_prim_alloc_huge_os_pages(void* hint_addr, size_t size, int numa_node, bool* is_zero, void** addr) {
494	  *is_zero = true;
495	  *addr = _mi_prim_alloc_huge_os_pagesx(hint_addr,size,numa_node);
496	  return (*addr != NULL ? 0 : (int)GetLastError());
497	}
