501	// Numa nodes
502	//---------------------------------------------
503	
504	size_t _mi_prim_numa_node(void) {
505	  USHORT numa_node = 0;
506	  if (pGetCurrentProcessorNumberEx != NULL && pGetNumaProcessorNodeEx != NULL) {
507	    // Extended API is supported
508	    MI_PROCESSOR_NUMBER pnum;
509	    (*pGetCurrentProcessorNumberEx)(&pnum);
510	    USHORT nnode = 0;
511	    BOOL ok = (*pGetNumaProcessorNodeEx)(&pnum, &nnode);
512	    if (ok) { numa_node = nnode; }
513	  }
514	  else if (pGetNumaProcessorNode != NULL) {
515	    // Vista or earlier, use older API that is limited to 64 processors. Issue #277
516	    DWORD pnum = GetCurrentProcessorNumber();
517	    UCHAR nnode = 0;
518	    BOOL ok = pGetNumaProcessorNode((UCHAR)pnum, &nnode);
519	    if (ok) { numa_node = nnode; }
520	  }
521	  return numa_node;
522	}
523	
524	size_t _mi_prim_numa_node_count(void) {
525	  ULONG numa_max = 0;
526	  if (pGetNumaHighestNodeNumber!=NULL) {
527	    (*pGetNumaHighestNodeNumber)(&numa_max);
528	  }
529	  // find the highest node number that has actual processors assigned to it. Issue #282
530	  while (numa_max > 0) {
531	    if (pGetNumaNodeProcessorMaskEx != NULL) {
532	      // Extended API is supported
533	      GROUP_AFFINITY affinity;
534	      if ((*pGetNumaNodeProcessorMaskEx)((USHORT)numa_max, &affinity)) {
535	        if (affinity.Mask != 0) break;  // found the maximum non-empty node
536	      }
537	    }
538	    else {
539	      // Vista or earlier, use older API that is limited to 64 processors.
540	      ULONGLONG mask;
541	      if (pGetNumaNodeProcessorMask != NULL) {
542	        if ((*pGetNumaNodeProcessorMask)((UCHAR)numa_max, &mask)) {
543	          if (mask != 0) break; // found the maximum non-empty node
544	        }
545	      };
546	    }
547	    // max node was invalid or had no processor assigned, try again
548	    numa_max--;
549	  }
550	  return ((size_t)numa_max + 1);
551	}
