557	
558	static mi_msecs_t mi_to_msecs(LARGE_INTEGER t) {
559	  static LARGE_INTEGER mfreq; // = 0
560	  if (mfreq.QuadPart == 0LL) {
561	    LARGE_INTEGER f;
562	    if (QueryPerformanceFrequency(&f)) {
563	      mfreq.QuadPart = f.QuadPart/1000LL;
564	    }
565	    if (mfreq.QuadPart == 0) mfreq.QuadPart = 1;
566	  }
567	  return (mi_msecs_t)(t.QuadPart / mfreq.QuadPart);
568	}
569	
570	mi_msecs_t _mi_prim_clock_now(void) {
571	  LARGE_INTEGER t;
572	  if (QueryPerformanceCounter(&t)) {
573	    return mi_to_msecs(t);
574	  }
575	  else {
576	    return 0;
577	  }
578	}
