601	  FILETIME ut;
602	  FILETIME st;
603	  FILETIME et;
604	  if (GetProcessTimes(GetCurrentProcess(), &ct, &et, &st, &ut)) {
605	    pinfo->utime = filetime_msecs(&ut);
