613	      pGetProcessMemoryInfo = (PGetProcessMemoryInfo)(void (*)(void))GetProcAddress(hDll, "GetProcessMemoryInfo");
614	      // mi_win_freelibrary(hDll, true);  // don't free
615	    }
616	  }
617	
618	  // get process info
619	  if (pGetProcessMemoryInfo != NULL) {
620	    PROCESS_MEMORY_COUNTERS info; _mi_memzero_var(info);
621	    if (pGetProcessMemoryInfo(GetCurrentProcess(), &info, sizeof(info))) {
622	      pinfo->current_rss = (size_t)info.WorkingSetSize;
623	      pinfo->peak_rss = (size_t)info.PeakWorkingSetSize;
624	      pinfo->current_commit = (size_t)info.PagefileUsage;
625	      pinfo->peak_commit = (size_t)info.PeakPagefileUsage;
626	      pinfo->page_faults = (size_t)info.PageFaultCount;
627	    }
628	  }
