633	//----------------------------------------------------------------
634	
635	void _mi_prim_out_stderr( const char* msg )
636	{
637	  // on windows with redirection, the C runtime cannot handle locale dependent output
638	  // after the main thread closes so we use direct console output.
639	  if (!_mi_preloading()) {
640	    static HANDLE hcon = INVALID_HANDLE_VALUE;
641	    #if MI_WIN_DESKTOP
642	    static bool hconIsConsole = false;
643	    #endif
644	    if (hcon == INVALID_HANDLE_VALUE) {
645	      hcon = GetStdHandle(STD_ERROR_HANDLE);   // returns NULL if no stderr is available
646	      #if MI_WIN_DESKTOP
647	      if (hcon==NULL) {
648	        AttachConsole(ATTACH_PARENT_PROCESS);  // if started from a parent console, try to attach to that
649	        hcon = GetStdHandle(STD_ERROR_HANDLE);
650	      }
651	      CONSOLE_SCREEN_BUFFER_INFO sbi;
652	      hconIsConsole = ((hcon != NULL && hcon != INVALID_HANDLE_VALUE) && GetConsoleScreenBufferInfo(hcon, &sbi));
653	      #endif
654	    }
655	    const size_t len = _mi_strlen(msg);
656	    if (len > 0 && len < UINT32_MAX) {
657	      DWORD written = 0;
658	      if (hcon != NULL && hcon != INVALID_HANDLE_VALUE) {
659	        #if MI_WIN_DESKTOP
660	        if (hconIsConsole) {
661	          WriteConsoleA(hcon, msg, (DWORD)len, &written, NULL);
662	        }
663	        else
664	        #endif
665	        {
666	          // use direct write in case stderr was redirected
667	          WriteFile(hcon, msg, (DWORD)len, &written, NULL);
668	        }
669	      }
670	      // don't fall back to fputs or _cputs as the crt can have it locked
671	    }
672	  }
673	}
