805	  static bool mi_module_is_dll(PVOID mod) {
806	    if (mod==NULL) return false;
807	    PIMAGE_DOS_HEADER imageDosHeader = (PIMAGE_DOS_HEADER)mod;
808	    PIMAGE_NT_HEADERS imageNtHeaders = (PIMAGE_NT_HEADERS)((unsigned char*)imageDosHeader + imageDosHeader->e_lfanew);
809	    return ((imageNtHeaders->FileHeader.Characteristics & IMAGE_FILE_DLL) == IMAGE_FILE_DLL);
810	  }
811	
812	  static bool mi_current_module_is_dll(void) {
813	    HMODULE mod = NULL;
814	    const BOOL ok = GetModuleHandleExA(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT, (LPCSTR)mi_current_module_is_dll, &mod);
815	    return (ok && mi_module_is_dll(mod));
816	  }
817	
818	  // Hook into CRT initialization and finalization.
819	  static void mi_cdecl mi_crt_done(void) {
820	    // mi_debug_out(mi_current_module_is_dll() ? "crt dll done\n" : "crt exe done\n");
821	    mi_win_main(NULL, DLL_PROCESS_DETACH, 0);
822	  }
823	
824	  static int mi_cdecl mi_crt_init(void) {
825	    // mi_debug_out(mi_current_module_is_dll() ? "crt dll init\n" : "crt exe init\n");
826	    if (mi_current_module_is_dll()) {
827	      // in a dll, atexit (crt_done) is called after tls process detach
828	      atexit(&mi_crt_done);
829	    }
830	    return 0;
831	  }
832	
833	  // We also hook into the Windows loader TLS initialization and finalization.
834	  static void NTAPI mi_tls_attach(PVOID module, DWORD reason, LPVOID reserved) {
835	    if (reason == DLL_THREAD_ATTACH) {
836	      //mi_debug_out("tls thread attach\n");
837	      mi_win_main(module, reason, reserved);
838	    }
839	    else if (reason == DLL_PROCESS_ATTACH) {
840	      // mi_debug_out(mi_module_is_dll(module) ? "tls dll process attach\n" : "tls exe process attach\n");
841	      // tls process attach is always called before crt init
842	      mi_win_main(module, reason, reserved);
843	    }
844	  }
845	
846	  static void NTAPI mi_tls_detach(PVOID module, DWORD reason, LPVOID reserved) {
847	    if (reason == DLL_THREAD_DETACH) {
848	      //mi_debug_out("tls thread detach\n");
849	      mi_win_main(module, reason, reserved);
850	    }
851	    else if (reason == DLL_PROCESS_DETACH) {
852	      // mi_debug_out(mi_module_is_dll(module) ? "tls dll process detach\n" : "tls exe process detach\n");
853	      if (!mi_module_is_dll(module)) {
854	        // in an exe, tls process detach is called after atexit (mi_crt_done)
855	        mi_win_main(module, reason, reserved);
856	      }
857	    }
858	  }
859	
860	  // Set up TLS callbacks in a statically linked library by using special data sections.
861	  // See <https://stackoverflow.com/questions/14538159/tls-callback-in-windows>
862	  // We use 2 entries to ensure we call attach events before constructors
863	  // are called, and detach events after destructors are called.
864	  // We also set up a CRT initialization callback.
865	  #if defined(__cplusplus)
866	  extern "C" {
867	  #endif
868	
869	  typedef int (mi_cdecl* mi_crt_callback_t)(void);
870	
871	  #if defined(_WIN64) && defined(_MSC_VER) // 64-bit
872	    #pragma comment(linker, "/INCLUDE:_tls_used")
873	    #pragma comment(linker, "/INCLUDE:_mi_tls_callback_pre")
874	    #pragma comment(linker, "/INCLUDE:_mi_tls_callback_post")
875	    #pragma comment(linker, "/INCLUDE:_mi_crt_callback_init")
876	    #pragma const_seg(".CRT$XLB")
877	      extern const PIMAGE_TLS_CALLBACK _mi_tls_callback_pre[];
878	      const PIMAGE_TLS_CALLBACK _mi_tls_callback_pre[] = { &mi_tls_attach };
879	    #pragma const_seg()
880	    #pragma const_seg(".CRT$XLY")
881	      extern const PIMAGE_TLS_CALLBACK _mi_tls_callback_post[];
882	      const PIMAGE_TLS_CALLBACK _mi_tls_callback_post[] = { &mi_tls_detach };
883	    #pragma const_seg()
884	    #pragma const_seg(".CRT$XIB")
885	      extern const mi_crt_callback_t _mi_crt_callback_init[];
886	      const mi_crt_callback_t _mi_crt_callback_init[] = { &mi_crt_init };
887	    #pragma const_seg()
888	  #elif defined(_MSC_VER) // 32-bit
889	    #pragma comment(linker, "/INCLUDE:__tls_used")
890	    #pragma comment(linker, "/INCLUDE:__mi_tls_callback_pre")
